commands.command:
set -eu
sudo -u postgres -- psql -v ON_ERROR_STOP=1 -d helpdesk <<'SQL'
SELECT setval(pg_get_serial_sequence('tickets','id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) AS repaired_to FROM tickets;
INSERT INTO tickets(subject) VALUES ('Sequence repair verification') RETURNING id, subject;
SQL

set -eu
sudo -u postgres -- psql -v ON_ERROR_STOP=1 -d helpdesk <<'SQL'
DELETE FROM tickets WHERE id = 101 AND subject = 'Sequence repair verification';
BEGIN;
INSERT INTO tickets(subject) VALUES ('Post-restart allocation probe') RETURNING id, subject;
ROLLBACK;
SELECT id, subject FROM tickets ORDER BY id;
SELECT COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, MAX(id) AS imported_max FROM tickets;
SELECT last_value, is_called FROM tickets_id_seq;
SQL
printf 'BOOT_ID='; cat /proc/sys/kernel/random/boot_id
printf 'OS='; cat /etc/redhat-release
printf 'KERNEL='; uname -r
printf 'SERVICE_ENABLED='; systemctl is-enabled postgresql
printf 'SERVICE_ACTIVE='; systemctl is-active postgresql
printf 'SOURCE_FILE='; stat -c '%n size=%s mode=%a owner=%U:%G' /srv/legacy2/postgresql-sequence-repair/tickets.sql
printf 'SOURCE_SHA256='; sha256sum /srv/legacy2/postgresql-sequence-repair/tickets.sql | awk '{print $1}'
